from typing import List


def findMaxSumWithSameFirstAndLastDigit(nums: List[int]) -> int:
    # 每个 (首位, 末位) 只需记住当前最大的一个数
    best_in_group = {}
    ans = -1
    for x in nums:
        s = str(x)
        key = (s[0], s[-1])
        if key in best_in_group:
            ans = max(ans, best_in_group[key] + x)
            best_in_group[key] = max(best_in_group[key], x)
        else:
            best_in_group[key] = x
    return ans


if __name__ == "__main__":
    assert findMaxSumWithSameFirstAndLastDigit([2, 36, 45, 306, 415]) == 460
    print("ok")

import java.util.*;

class Solution {
    int findMaxSumWithSameFirstAndLastDigit(int[] nums) {
        Map<String, List<Integer>> buckets = new HashMap<>();
        for (int x : nums) {
            String s = String.valueOf(x);
            String key = "" + s.charAt(0) + s.charAt(s.length() - 1);
            buckets.computeIfAbsent(key, k -> new ArrayList<>()).add(x);
        }
        int best = -1;
        for (var vals : buckets.values()) {
            if (vals.size() >= 2) {
                Collections.sort(vals, Collections.reverseOrder());
                best = Math.max(best, vals.get(0) + vals.get(1));
            }
        }
        return best;
    }
}

class Solution {
public:
    int findMaxSumWithSameFirstAndLastDigit(vector<int>& nums) {
        unordered_map<string, vector<int>> buckets;
        for (int x : nums) {
            string s = to_string(x);
            string key{s.front(), s.back()};
            buckets[key].push_back(x);
        }
        int best = -1;
        for (auto& [k, vals] : buckets) {
            if (vals.size() >= 2) {
                sort(vals.begin(), vals.end(), greater<int>());
                best = max(best, vals[0] + vals[1]);
            }
        }
        return best;
    }
};
